    "eHint": "def kosaraju_scc(n: int, edges: list[tuple[int, int]]) -> list[list[int]]:\n    adj = [[] for _ in range(n)]\n    rev = [[] for _ in range(n)]\n    for u, v in edges:\n        adj[u].append(v)\n        rev[v].append(u)\n    vis = [False] * n\n    order = []\n    for start in range(n):\n        if vis[start]:\n            continue\n        stack = [(start, 0)]\n        vis[start] = True\n        while stack:\n            u, idx = stack[-1]\n            if idx < len(adj[u]):\n                stack[-1] = (u, idx + 1)\n                v = adj[u][idx]\n                if not vis[v]:\n                    vis[v] = True\n                    stack.append((v, 0))\n            else:\n                stack.pop()\n                order.append(u)\n    vis2 = [False] * n\n    sccs = []\n    for root in reversed(order):\n        if vis2[root]:\n            continue\n        comp = []\n        st = [root]\n        vis2[root] = True\n        while st:\n            u = st.pop()\n            comp.append(u)\n            for v in rev[u]:\n                if not vis2[v]:\n                    vis2[v] = True\n                    st.append(v)\n        sccs.append(sorted(comp))\n    return sorted(sccs)",
