    "aHint": "def tarjan_condensation_stats(n: int, edges: list[tuple[int, int]]) -> tuple[int, int, int]:\n    adj = [[] for _ in range(n)]\n    for u, v in edges:\n        adj[u].append(v)\n    disc = [-1] * n\n    low = [0] * n\n    on_st = [False] * n\n    st = []\n    comp_id = [-1] * n\n    timer = [0]\n    scc_count = [0]\n    def dfs(u):\n        disc[u] = low[u] = timer[0]\n        timer[0] += 1\n        st.append(u)\n        on_st[u] = True\n        for v in adj[u]:\n            if disc[v] == -1:\n                dfs(v)\n                low[u] = min(low[u], low[v])\n            elif on_st[v]:\n                low[u] = min(low[u], disc[v])\n        if low[u] == disc[u]:\n            cid = scc_count[0]\n            scc_count[0] += 1\n            while True:\n                w = st.pop()\n                on_st[w] = False\n                comp_id[w] = cid\n                if w == u:\n                    break\n    for i in range(n):\n        if disc[i] == -1:\n            dfs(i)\n    k = scc_count[0]\n    indeg = [0] * k\n    outdeg = [0] * k\n    seen = set()\n    for u, v in edges:\n        cu, cv = comp_id[u], comp_id[v]\n        if cu != cv and (cu, cv) not in seen:\n            seen.add((cu, cv))\n            outdeg[cu] += 1\n            indeg[cv] += 1\n    return (k, sum(1 for d in indeg if d == 0), sum(1 for d in outdeg if d == 0))",
