    "aStarter": "from collections import deque\n\nclass BottleneckTree:\n    def __init__(self, n: int, edges: list[tuple[int, int, int]]):\n        # TODO\n        pass\n\n    def max_edge_on_path(self, u: int, v: int) -> int:\n        # TODO\n        pass",
    "aHint": "from collections import deque\n\nclass BottleneckTree:\n    def __init__(self, n: int, edges: list[tuple[int, int, int]]):\n        self.LOG = max(1, n.bit_length())\n        adj = [[] for _ in range(n)]\n        for u, v, w in edges:\n            adj[u].append((v, w))\n            adj[v].append((u, w))\n        self.up = [[0] * n for _ in range(self.LOG)]\n        self.mx = [[0] * n for _ in range(self.LOG)]\n        self.depth = [0] * n\n        vis = [False] * n\n        vis[0] = True\n        q = deque([0])\n        while q:\n            u = q.popleft()\n            for v, w in adj[u]:\n                if not vis[v]:\n                    vis[v] = True\n                    self.depth[v] = self.depth[u] + 1\n                    self.up[0][v] = u\n                    self.mx[0][v] = w\n                    q.append(v)\n        for k in range(1, self.LOG):\n            for v in range(n):\n                p = self.up[k - 1][v]\n                self.up[k][v] = self.up[k - 1][p]\n                self.mx[k][v] = max(self.mx[k - 1][v], self.mx[k - 1][p])\n\n    def max_edge_on_path(self, u: int, v: int) -> int:\n        if u == v:\n            return 0\n        if self.depth[u] < self.depth[v]:\n            u, v = v, u\n        ans = 0\n        diff = self.depth[u] - self.depth[v]\n        for k in range(self.LOG):\n            if diff & (1 << k):\n                ans = max(ans, self.mx[k][u])\n                u = self.up[k][u]\n        if u == v:\n            return ans\n        for k in range(self.LOG - 1, -1, -1):\n            if self.up[k][u] != self.up[k][v]:\n                ans = max(ans, self.mx[k][u], self.mx[k][v])\n                u = self.up[k][u]\n                v = self.up[k][v]\n        return max(ans, self.mx[0][u], self.mx[0][v])",
