    "aHint": "from collections import defaultdict, OrderedDict\n\nclass LFUCache:\n    def __init__(self, capacity: int):\n        self.cap = capacity\n        self.vals = {}\n        self.freq = {}\n        self.buckets = defaultdict(OrderedDict)\n        self.min_f = 0\n\n    def _bump(self, key: int):\n        f = self.freq[key]\n        del self.buckets[f][key]\n        if not self.buckets[f] and f == self.min_f:\n            self.min_f += 1\n        self.freq[key] = f + 1\n        self.buckets[f + 1][key] = None\n\n    def get(self, key: int) -> int:\n        if key not in self.vals:\n            return -1\n        self._bump(key)\n        return self.vals[key]\n\n    def put(self, key: int, value: int) -> None:\n        if self.cap <= 0:\n            return\n        if key in self.vals:\n            self.vals[key] = value\n            self._bump(key)\n            return\n        if len(self.vals) == self.cap:\n            evict_k, _ = self.buckets[self.min_f].popitem(last=False)\n            del self.vals[evict_k]\n            del self.freq[evict_k]\n        self.vals[key] = value\n        self.freq[key] = 1\n        self.buckets[1][key] = None\n        self.min_f = 1",
