    "aHint": "class _ISLNode:\n    def __init__(self, val: int, level: int):\n        self.val = val\n        self.fwd = [None] * level\n\nclass IndexedSkipList:\n    def __init__(self, max_level: int = 8):\n        self.max_lvl = max_level\n        self.head = _ISLNode(-10**18, max_level)\n        self.level = 1\n        self._seed = 987654321\n\n    def _lower_bound(self, val: int):\n        cur = self.head\n        for i in range(self.level - 1, -1, -1):\n            while cur.fwd[i] is not None and cur.fwd[i].val < val:\n                cur = cur.fwd[i]\n        return cur\n\n    def insert(self, val: int) -> None:\n        upd = [self.head] * self.max_lvl\n        cur = self.head\n        for i in range(self.level - 1, -1, -1):\n            while cur.fwd[i] is not None and cur.fwd[i].val < val:\n                cur = cur.fwd[i]\n            upd[i] = cur\n        lvl = 1\n        while lvl < self.max_lvl:\n            self._seed = (1664525 * self._seed + 1013904223) & 0xFFFFFFFF\n            if (self._seed & 1) == 0:\n                break\n            lvl += 1\n        if lvl > self.level:\n            self.level = lvl\n        node = _ISLNode(val, lvl)\n        for i in range(lvl):\n            node.fwd[i] = upd[i].fwd[i]\n            upd[i].fwd[i] = node\n\n    def ceiling(self, val: int):\n        nxt = self._lower_bound(val).fwd[0]\n        return nxt.val if nxt is not None else None\n\n    def range_query(self, lo: int, hi: int) -> list[int]:\n        out = []\n        cur = self._lower_bound(lo).fwd[0]\n        while cur is not None and cur.val <= hi:\n            out.append(cur.val)\n            cur = cur.fwd[0]\n        return out",
